import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR-0006: Production Update Signing-Key Custody","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/adrs/0006-production-signing-key-custody.md"},"headers":[],"relativePath":"sovereign-os/adrs/0006-production-signing-key-custody.md","filePath":"sovereign-os/adrs/0006-production-signing-key-custody.md"}'),n={name:"sovereign-os/adrs/0006-production-signing-key-custody.md"};function s(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0006-production-update-signing-key-custody" tabindex="-1">ADR-0006: Production Update Signing-Key Custody <a class="header-anchor" href="#adr-0006-production-update-signing-key-custody" aria-label="Permalink to &quot;ADR-0006: Production Update Signing-Key Custody&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2026-07-30 <strong>Decision owner:</strong> Project creator <strong>Related RFC:</strong> <a href="./../rfcs/0014-appliance-update-system.html">RFC-0014</a><strong>Related milestone:</strong> <a href="./../roadmap/01-1-update-foundation.html">Appliance Update Foundation</a><strong>Supersedes:</strong> None</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Every signed release manifest is verified against a trust store of <code>&lt;key-id&gt;.pem</code> / <code>&lt;key-id&gt;.json</code> pairs under <code>/etc/sovereign/update-trust.d/</code> (schema, channel scoping, and revocation are already implemented — see <code>load_trusted_key()</code> in <code>sovereign-update</code>). The shipped trust store is intentionally empty:</p><blockquote><p>No preview key is installed until release-key custody and rotation are approved. An empty trust store fails closed and prevents update installation. — <code>image-builder/sovereign/layer/sovereign-proof.rootfs-overlay/etc/sovereign/update-trust.d/README</code></p></blockquote><p>Every key used so far — including the <code>preview-local</code> and <code>restore-qual-local</code> keys used during hardware qualification — has been an ephemeral, disposable Ed25519 keypair generated on an operator&#39;s own machine for a single qualification session and discarded afterward. That is appropriate for qualification but is not a production key: no real household should ever install a Sovereign OS update signed by a key with no defined custody, rotation, or revocation story.</p><p>This ADR does not choose custody for the project owner. It lays out the realistic options at this project&#39;s current scale (a small/solo maintainer team, self-hosted household infrastructure, budget-conscious) so a deliberate choice can be recorded and revisited as the project grows.</p><h3 id="what-the-signing-key-actually-protects" tabindex="-1">What the signing key actually protects <a class="header-anchor" href="#what-the-signing-key-actually-protects" aria-label="Permalink to &quot;What the signing key actually protects&quot;">​</a></h3><p>A holder of the production private key can produce a manifest that every device trusting that <code>key_id</code> will accept as authentic for its scoped channel(s). Layered defenses (archive-safety validation, Compose/Nginx config validation, digest pinning, health-gated activation, automatic rollback) limit what a malicious <em>payload</em> can do once accepted, but they do not substitute for keeping the key itself out of reach of anyone who shouldn&#39;t have it. For a device that answers DNS for someone&#39;s home network and holds their Pi-hole credentials, this is the update system&#39;s single highest-value secret.</p><h3 id="constraints-already-fixed-by-the-existing-design" tabindex="-1">Constraints already fixed by the existing design <a class="header-anchor" href="#constraints-already-fixed-by-the-existing-design" aria-label="Permalink to &quot;Constraints already fixed by the existing design&quot;">​</a></h3><ul><li>Algorithm is fixed: Ed25519 only (<code>manifest[&quot;signing&quot;][&quot;algorithm&quot;] == &quot;Ed25519&quot;</code>).</li><li>Trust is per-key, per-channel: a key&#39;s JSON metadata scopes it to <code>preview</code> and/or <code>stable</code>. Separate keys per channel are already supported without any code change — only a custody decision.</li><li>Revocation is already implemented at the verification layer (<code>metadata[&quot;revoked&quot;]</code>), but <strong>distribution of a revoked-flag update to already-flashed devices is not yet automated.</strong> Today it would require either a manual per-device file copy (as done for qualification) or waiting for the &quot;Update Discovery and Console Controls&quot; milestone to ship signed trust-metadata distribution. This ADR&#39;s recommendation should account for that gap, not assume revocation is instantly effective.</li><li>The trust store ships baked into the base image (like <code>update-policy.json</code>) but is currently empty; once a production key exists, its <strong>public</strong> key and metadata are natural candidates to add to the image-builder overlay so future base images trust it out of the box, removing the manual per-device installation step used during qualification.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The project owner selected <strong>a variant of Option B (password-manager-held key), with Option C (hardware security key) as an accepted future upgrade path</strong> rather than a required starting point.</p><ul><li>The production Ed25519 private key is generated and stored as an encrypted secret in the maintainer&#39;s password manager. This gives the key professional-grade encryption at rest and, importantly, solves the single-point-of-failure backup problem that Option A (bare offline device) has on its own — most password managers replicate across devices and have their own account-recovery process. <ul><li>When a release needs signing, the key is decrypted out to a machine to run the actual <code>openssl pkeyutl -sign -rawin</code> operation, then that plaintext copy should be removed from disk afterward. Preferring a machine that is not your everyday browsing/email machine for that moment further reduces exposure, but is a practice recommendation, not a hard requirement of this decision.</li><li>This does <strong>not</strong> eliminate the exposure window at signing time the way a hardware token would — see the Risks below.</li></ul></li><li>A hardware security key (Option C) remains open as a future upgrade once its exact Ed25519/PKCS#11 compatibility with this project&#39;s signing flow is verified by a hands-on spike. Nothing about today&#39;s decision blocks moving to it later; the trust-store mechanism only cares about the public key and <code>key_id</code>, not how the private half was held.</li><li>Options A (pure offline device), D (cloud KMS), and E (threshold signing) were not selected — D specifically because it introduces a third party into the trust chain, which the project owner weighed against the project&#39;s self-hosted values as described in the Options section below.</li></ul><h2 id="key-generated" tabindex="-1">Key Generated <a class="header-anchor" href="#key-generated" aria-label="Permalink to &quot;Key Generated&quot;">​</a></h2><p><strong>2026-07-31.</strong> The production key exists: <code>sovereign-production-1</code>, Ed25519, scoped to both <code>preview</code> and <code>stable</code> channels (one key, both channels — chosen over separate per-channel keys for simplicity at solo-maintainer scale; splitting later via <code>rotate-trust</code> needs no code change). The private key was generated locally and is held as an encrypted secret in the maintainer&#39;s password manager per the Decision above; it was never committed to this repository. The public half (<code>sovereign-production-1.pem</code>/<code>.json</code>) is now baked into <code>image-builder/sovereign/layer/sovereign-proof.rootfs-overlay/etc/sovereign/update-trust.d/</code>, so future base images trust it out of the box instead of shipping an empty trust store.</p><p><strong>2026-07-31, same day.</strong> <code>v0.1.0-preview.17</code> became the first release signed with this key: built via the normal workflow, signed offline by the maintainer (private key never handled by the assistant), and verified end-to-end by <code>sovereign-update check</code> against the real GitHub API on physical Raspberry Pi 5 hardware — see the <a href="./../research/first-production-signed-release-qualification-report.html">first production-signed release qualification report</a>.</p><p><strong>2026-07-31, later the same day.</strong> <code>v0.1.0-preview.17</code> was then genuinely <em>installed</em> on that same device via a full <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> transaction, confirmed committed across a reboot — see the <a href="./../research/first-production-signed-release-install-qualification-report.html">install qualification report</a>, which also documents a real <code>sovereign-proof.service</code> regression found and fixed along the way. <code>restore</code> was then qualified against that install&#39;s own pre-activation backup — see the <a href="./../research/production-signed-restore-qualification-report.html">production-signed restore qualification report</a>. <code>prune</code> and <code>rotate-trust</code> still haven&#39;t been exercised as part of an actual signed-release install cycle.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><h3 id="option-a-—-offline-air-gapped-signing-device" tabindex="-1">Option A — Offline, air-gapped signing device <a class="header-anchor" href="#option-a-—-offline-air-gapped-signing-device" aria-label="Permalink to &quot;Option A — Offline, air-gapped signing device&quot;">​</a></h3><p>Generate and keep the private key only on a device that is never connected to any network: a spare Raspberry Pi, an old laptop, or even a write-protected USB boot environment. Manifests to be signed are moved onto the device (SD card / USB), signed with <code>openssl pkeyutl -sign -rawin</code> exactly as the qualification tooling already does, and the signature is moved back off.</p><ul><li><strong>Cost:</strong> near zero — reuses hardware most maintainers already have.</li><li><strong>Fits the project&#39;s own &quot;sovereign&quot;/self-hosted values</strong> — no third party ever holds the key.</li><li><strong>Downsides:</strong> fully manual (slower release cadence), a single point of physical loss/theft/fire unless backed up, no built-in access log, key backup (e.g., an encrypted copy on separate media in a separate physical location) is the maintainer&#39;s own responsibility to set up and remember.</li></ul><h3 id="option-b-—-passphrase-protected-key-on-the-maintainer-s-regular-machine" tabindex="-1">Option B — Passphrase-protected key on the maintainer&#39;s regular machine <a class="header-anchor" href="#option-b-—-passphrase-protected-key-on-the-maintainer-s-regular-machine" aria-label="Permalink to &quot;Option B — Passphrase-protected key on the maintainer&#39;s regular machine&quot;">​</a></h3><p>The simplest option: an Ed25519 key encrypted at rest (e.g., <code>openssl genpkey</code> output protected by a passphrase, or a standard encrypted keychain), used directly from a day-to-day development machine.</p><ul><li><strong>Cost:</strong> zero, fastest to set up.</li><li><strong>Downsides:</strong> weakest option here. Malware or compromise of that machine at the moment the passphrase is entered exposes the key directly. This is materially the same trust level as the disposable qualification keys already used — arguably not a real step up to &quot;production.&quot;</li></ul><h3 id="option-c-—-hardware-security-key-smartcard" tabindex="-1">Option C — Hardware security key / smartcard <a class="header-anchor" href="#option-c-—-hardware-security-key-smartcard" aria-label="Permalink to &quot;Option C — Hardware security key / smartcard&quot;">​</a></h3><p>A dedicated hardware token (e.g., a FIDO2/OpenPGP-capable security key) generates the private key on-chip; it never leaves the device, and signing requires physical possession plus a PIN or touch.</p><ul><li><strong>Strong protection against remote compromise</strong> — malware on the signing machine can request a signature but cannot exfiltrate the key.</li><li><strong>Cost:</strong> modest (roughly $25–$70 for a suitable token).</li><li><strong>Feasibility caveat, not yet verified:</strong> the update tooling signs via <code>openssl pkeyutl -sign -rawin</code> against a raw manifest byte stream. Whether a specific token exposes Ed25519 signing through a PKCS#11/engine interface compatible with that exact flow needs a hands-on spike before committing to this option — don&#39;t take it as validated by this ADR.</li><li><strong>Downsides:</strong> token loss means a real rotation event; a lost token cannot be &quot;restored,&quot; only replaced.</li></ul><h3 id="option-d-—-cloud-kms-e-g-aws-kms-google-cloud-kms-hashicorp-vault" tabindex="-1">Option D — Cloud KMS (e.g., AWS KMS, Google Cloud KMS, HashiCorp Vault) <a class="header-anchor" href="#option-d-—-cloud-kms-e-g-aws-kms-google-cloud-kms-hashicorp-vault" aria-label="Permalink to &quot;Option D — Cloud KMS (e.g., AWS KMS, Google Cloud KMS, HashiCorp Vault)&quot;">​</a></h3><p>The private key is generated and held inside a managed key-management service; signing happens via an API call, never exposing key material.</p><ul><li><strong>Strongest operational story:</strong> audit logs, access control, straightforward to wire into CI for automated release signing later.</li><li><strong>Downsides:</strong> recurring cost; introduces a third party into the trust chain for a project whose product explicitly avoids third-party dependencies for the household&#39;s own data — worth weighing against the project&#39;s stated values even though the <em>signing infrastructure</em> isn&#39;t the shipped <em>product</em>. Ed25519 support and exact API shape vary by provider and should be verified current before relying on this option; don&#39;t take Ed25519 availability as confirmed by this ADR. Adds IAM/service -account complexity that is arguably disproportionate for a solo maintainer today.</li></ul><h3 id="option-e-—-threshold-multi-party-signing" tabindex="-1">Option E — Threshold / multi-party signing <a class="header-anchor" href="#option-e-—-threshold-multi-party-signing" aria-label="Permalink to &quot;Option E — Threshold / multi-party signing&quot;">​</a></h3><p>Split the key (e.g., Shamir&#39;s Secret Sharing) across multiple trusted parties so no single person can sign alone.</p><ul><li>Meaningful once the project has more than one person who should be able to authorize a release.</li><li><strong>Not recommended now</strong> — every other document in this repository lists a single &quot;Decision owner: Project creator.&quot; Revisit this option if that changes.</li></ul><h2 id="initial-recommendation-superseded-by-decision-above" tabindex="-1">Initial Recommendation (superseded by Decision above) <a class="header-anchor" href="#initial-recommendation-superseded-by-decision-above" aria-label="Permalink to &quot;Initial Recommendation (superseded by Decision above)&quot;">​</a></h2><p>Before a decision was made, this ADR initially leaned toward Option A (offline air-gapped device) or Option C (hardware security key) as the best fit for the project&#39;s scale, budget, and self-hosted values, and cautioned that a bare passphrase-protected key (Option B) was only marginally stronger than the disposable qualification keys already in use. The project owner weighed that tradeoff and chose the password-manager variant recorded in Decision above specifically because it closes the backup/durability gap that made plain Option B weak, while keeping Option C open as a later upgrade. Recorded here for context, not as standing guidance.</p><h2 id="rotation" tabindex="-1">Rotation <a class="header-anchor" href="#rotation" aria-label="Permalink to &quot;Rotation&quot;">​</a></h2><p><strong>Update since this ADR was first drafted:</strong> routine rotation is now implemented as <code>sovereign-update rotate-trust</code> (see the &quot;Trust Rotation v1&quot; section of <code>update/README.md</code>), which delivers a new trust key through the same signed-artifact mechanism as everything else, rather than a manual <code>sudo install</code> of raw key files. The realistic flow given this ADR&#39;s single-key custody decision:</p><ol><li>Generate the new keypair using the chosen custody mechanism (currently: password manager, decrypted onto a signing machine when needed).</li><li>Sign a trust-rotation manifest, using the <em>current</em> key, that both <code>add</code>s the new key and <code>revoke</code>s the current one in the same manifest — an atomic handoff with no gap where two keys are simultaneously trusted unless that overlap is explicitly wanted (a manifest can also add-only and revoke the old key in a later, separate manifest if a longer overlap window is preferred).</li><li>Run <code>sovereign-update rotate-trust</code> with that manifest against each device. Its built-in lockout check refuses to apply any rotation that would leave the channel with zero trusted keys, so a mistake here cannot brick a device&#39;s ability to trust future updates.</li><li>Sign subsequent releases with the new key.</li><li>Reaching <em>already-flashed</em> devices with step 3 is still a manual, operator-run command today — that part of the distribution gap remains open until &quot;Update Discovery and Console Controls&quot; can fetch and apply a rotation manifest automatically. What&#39;s closed is the <em>safety</em> of the rotation action itself: it&#39;s now a verified, atomic, signed operation instead of copying trust-me-bare files over SSH.</li></ol><h2 id="revocation" tabindex="-1">Revocation <a class="header-anchor" href="#revocation" aria-label="Permalink to &quot;Revocation&quot;">​</a></h2><p>If a key is known or suspected compromised: immediately stop signing with it, and treat every already-signed release under that key as untrustworthy going forward (the manifest schema has no separate revocation-of-past- releases mechanism — revocation is key-scoped, not release-scoped).</p><p><code>sovereign-update rotate-trust</code> can carry a <code>revoke</code> operation and works for <em>precautionary</em> or planned revocation exactly like rotation above — a still-good signature applies the revoke-plus-replacement atomically to each device, still gated on manual per-device delivery until Update Discovery exists.</p><p>For a <em>confirmed adversarial compromise</em>, be precise about what <code>rotate-trust</code> does and doesn&#39;t buy you: it only accepts manifests signed by the compromised key itself (or another already-trusted key), so whether the legitimate operator&#39;s revocation reaches a given device before an attacker uses the same stolen key to push something malicious to that device is a race, not a guarantee — key compromise means an adversary can produce equally &quot;validly signed&quot; rotation manifests too. The only fully reliable recovery from a confirmed compromise is treating every device as needing a fresh trust root, which today means a reflash with a new key baked into the image (see Recovery below); <code>rotate-trust</code> is a convenience for the routine case, not a substitute for that fallback in the adversarial case.</p><h2 id="recovery-if-the-key-is-lost-or-the-custodian-is-unavailable" tabindex="-1">Recovery if the key is lost or the custodian is unavailable <a class="header-anchor" href="#recovery-if-the-key-is-lost-or-the-custodian-is-unavailable" aria-label="Permalink to &quot;Recovery if the key is lost or the custodian is unavailable&quot;">​</a></h2><p>Because trust is rooted in whatever key(s) are already installed on a device, losing the only trusted production key with no backup would leave existing devices unable to verify <em>any</em> future signed update — the fallback is a full base-image reflash carrying a new key baked into the overlay (the same mechanism already used to ship <code>update-policy.json</code>). Whichever custody option is chosen, an encrypted backup of the private key material, stored somewhere physically separate from the primary custody location, should be treated as a requirement, not an optional nicety — the alternative is an unrecoverable trust root.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Removes the last structural blocker called out by the trust-store README before any real (non-qualification) signed release can be installed by a normal user.</li><li>Makes the rotation/revocation story explicit instead of implicit.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>Whichever option is chosen adds an ongoing operational responsibility (custody, backup, eventual rotation) that today&#39;s ephemeral-qualification-key workflow does not have.</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>Choosing Option B (or any option) without a real backup plan creates a single point of failure for the entire update trust chain.</li><li>Revocation and rotation are both gated on a distribution mechanism (&quot;Update Discovery and Console Controls&quot;) that has not shipped yet; choosing a custody option does not by itself close that gap.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><h3 id="no-production-key-yet-keep-using-ephemeral-qualification-keys" tabindex="-1">No production key yet; keep using ephemeral qualification keys <a class="header-anchor" href="#no-production-key-yet-keep-using-ephemeral-qualification-keys" aria-label="Permalink to &quot;No production key yet; keep using ephemeral qualification keys&quot;">​</a></h3><p>Rejected as a standing state — it is fine for continued hardware qualification, but it cannot be how a real user&#39;s device is ever asked to trust an update. The empty trust store already fails closed specifically to prevent this from happening by accident.</p><h2 id="validation-and-revisit-conditions" tabindex="-1">Validation and Revisit Conditions <a class="header-anchor" href="#validation-and-revisit-conditions" aria-label="Permalink to &quot;Validation and Revisit Conditions&quot;">​</a></h2><p>Revisit this ADR if: the project gains additional trusted maintainers (favoring Option E), the release cadence grows enough that manual air-gapped signing (Option A) becomes a bottleneck (favoring Option C or D), or a hands-on spike shows the intended hardware token does not support the signing flow this project&#39;s tooling uses (ruling out Option C as written).</p>',57)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
